cards: [KanbanCard]
    {
        didSet
        {
            let previous = Dictionary(
                oldValue.map
                {
                    ($0.id, $0)
                },
                uniquingKeysWith:
                {
                    first, _ in
                    first
                }
            )
            for index in cards.indices
            {
                if let old = previous[cards[index].id]
                {
                    cards[index] = cards[index].recordingEdits(from: old)
                }
            }
        }
    }
